/**
 * Clear cached benchmark results (e.g., for testing or manual refresh).
 */
export async function clearBenchmarkCache(): Promise<void> {
  const req = indexedDB.open(DB_NAME, 1);

  return new Promise((resolve, reject) => {
    req.onerror = () => reject(req.error);
    req.onsuccess = () => {
      const db = req.result;
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const clearReq = store.clear();

      clearReq.onsuccess = () => {
        db.close();
        resolve();
      };

      clearReq.onerror = () => {
        db.close();
        reject(clearReq.error);
      };
    };

    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, {keyPath: 'key'});
      }
    };
  });
}

/**
 * Clean up expired cache entries.
 *
 * Removes cached benchmark results that are older than the TTL.
 * This is optional maintenance to keep the cache size manageable.
 *
 * @returns Promise resolving to number of entries removed
 */
export async function cleanupExpiredCacheEntries(): Promise<number> {
  const req = indexedDB.open(DB_NAME, 1);
  const now = Date.now();

  return new Promise((resolve, reject) => {
    req.onerror = () => reject(req.error);
    req.onsuccess = () => {
      const db = req.result;
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const getAllReq = store.getAll();

      getAllReq.onsuccess = () => {
        const entries = getAllReq.result;
        let removedCount = 0;

        for (const entry of entries) {
          const age = now - entry.result.timestamp;
          if (age > CACHE_TTL_MS) {
            store.delete(entry.key);
            removedCount++;
          }
        }

        tx.oncomplete = () => {
          db.close();
          console.log(`Cleaned up ${removedCount} expired cache entries`);
          resolve(removedCount);
        };

        tx.onerror = () => {
          db.close();
          reject(tx.error);
        };
      };

      getAllReq.onerror = () => {
        db.close();
        reject(getAllReq.error);
      };
    };

    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, {keyPath: 'key'});
      }
    };
  });
}

